"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3434],{53478:e=>{e.exports=JSON.parse('{"functions":[{"name":"RandomPoint","desc":"","params":[{"name":"random","desc":"","lua_type":"Random"},{"name":"centre","desc":"","lua_type":"Vector3"},{"name":"radius","desc":"","lua_type":"number"}],"returns":[{"desc":"A point on the horizontal disc of `radius` around `centre`, uniformly distributed, at the centre\'s height.","lua_type":"Vector3"}],"function_type":"static","source":{"line":192,"path":"lib/Brain/States.luau"}},{"name":"Patrol","desc":"Walks the points in order, forever. The index survives leaving and re-entering the state, so\\nan enemy that broke off to investigate resumes where it was. A point that cannot be reached\\nis skipped.","params":[{"name":"options","desc":"","lua_type":"PatrolOptions"}],"returns":[{"desc":"","lua_type":"State"}],"function_type":"static","source":{"line":242,"path":"lib/Brain/States.luau"}},{"name":"Investigate","desc":"Goes to one place and, once there (or once the path fails), lingers and moves on to `Then`.\\nThe place is read on entry, so a newer noise re-enters the state through a transition rather\\nthan pulling the agent mid-walk.","params":[{"name":"options","desc":"","lua_type":"InvestigateOptions"}],"returns":[{"desc":"","lua_type":"State"}],"function_type":"static","source":{"line":365,"path":"lib/Brain/States.luau"}},{"name":"Search","desc":"Picks a few random points around a spot and walks them in turn until `Duration` runs out:\\nthe \\"where did they go\\" after losing sight. A point the navigator cannot reach is skipped.","params":[{"name":"options","desc":"","lua_type":"SearchOptions"}],"returns":[{"desc":"","lua_type":"State"}],"function_type":"static","source":{"line":454,"path":"lib/Brain/States.luau"}},{"name":"Wander","desc":"Drifts between random points around home, pausing at each. The Guardian\'s idle, as a line.","params":[{"name":"options","desc":"","lua_type":"WanderOptions?"}],"returns":[{"desc":"","lua_type":"State"}],"function_type":"static","source":{"line":536,"path":"lib/Brain/States.luau"}},{"name":"Roam","desc":"Asks the [Interest] map for the best point, walks there, lingers, marks it visited, and asks\\nagain. Points the agent just visited score nothing, so it spreads its search. When no point\\nscores, or `Duration` runs out, it enters `Then`.","params":[{"name":"options","desc":"","lua_type":"RoamOptions"}],"returns":[{"desc":"","lua_type":"State"}],"function_type":"static","source":{"line":632,"path":"lib/Brain/States.luau"}},{"name":"Wait","desc":"Stops and stands still: dormant, stunned, listening. With `Duration` and `Then` it moves on by\\nitself; otherwise its transitions decide.","params":[{"name":"options","desc":"","lua_type":"WaitOptions?"}],"returns":[{"desc":"","lua_type":"State"}],"function_type":"static","source":{"line":737,"path":"lib/Brain/States.luau"}}],"properties":[],"types":[{"name":"PatrolOptions","desc":"","fields":[{"name":"Points","lua_type":"string | { Vector3 } | (agent: Agent) -> { Vector3 }","desc":"The route: a `Data` key holding a list, the list itself, or a function. Required."},{"name":"Order","lua_type":"\\"Loop\\" | \\"PingPong\\" | \\"Random\\"?","desc":"Loop back to the first point, walk the list both ways, or pick any other point. Default `\\"Loop\\"`."},{"name":"Pause","lua_type":"number | { number }?","desc":"Seconds to stand at each point, or a `{ min, max }` range. Default none."},{"name":"Speed","lua_type":"number?","desc":"Set on entry."},{"name":"Random","lua_type":"Random?","desc":"For `Random` order and a ranged `Pause`. Default `agent.Data.Random`, else a new one."},{"name":"Key","lua_type":"string?","desc":"The `Data` key for the current index. Default `\\"Patrol\\"`."},{"name":"Transitions","lua_type":"{ Transition }?","desc":""},{"name":"Enter","lua_type":"((agent: Agent) -> ())?","desc":""},{"name":"Exit","lua_type":"((agent: Agent) -> ())?","desc":""}],"source":{"line":221,"path":"lib/Brain/States.luau"}},{"name":"InvestigateOptions","desc":"","fields":[{"name":"Target","lua_type":"string | Vector3 | (agent: Agent) -> Vector3?","desc":"Where to go: a blackboard or `Data` key such as `\\"HeardPosition\\"`, a position, or a function. Read once on entry. Required."},{"name":"Then","lua_type":"string?","desc":"The state to enter when there, when the target is missing, or when the path fails. Without it the state waits for a transition."},{"name":"Linger","lua_type":"number | { number }?","desc":"Seconds to stand at the spot before `Then`. Default `0`."},{"name":"Acknowledge","lua_type":"string?","desc":"A blackboard key to [Agent:Acknowledge] on entry, such as `\\"HeardAt\\"`, so the noise that brought the agent here does not count as new again."},{"name":"Speed","lua_type":"number?","desc":"Set on entry."},{"name":"Random","lua_type":"Random?","desc":"For a ranged `Linger`."},{"name":"Key","lua_type":"string?","desc":"Default `\\"Investigate\\"`."},{"name":"Transitions","lua_type":"{ Transition }?","desc":""},{"name":"Enter","lua_type":"((agent: Agent) -> ())?","desc":""},{"name":"Exit","lua_type":"((agent: Agent) -> ())?","desc":""}],"source":{"line":343,"path":"lib/Brain/States.luau"}},{"name":"SearchOptions","desc":"","fields":[{"name":"Around","lua_type":"string | Vector3 | (agent: Agent) -> Vector3?","desc":"The centre: usually `\\"SeenPosition\\"` or `\\"LastKnownPosition\\"`. Missing means the agent\'s own position. Read once on entry."},{"name":"Radius","lua_type":"number?","desc":"Studs around the centre the points are picked in. Default `12`."},{"name":"Points","lua_type":"number?","desc":"How many points to pick. They are walked in turn and cycled until `Duration` runs out. Default `3`."},{"name":"Duration","lua_type":"number | { number }?","desc":"Seconds to search before `Then`. Default `15`."},{"name":"Then","lua_type":"string?","desc":"The state to enter when time is up. Without it the state searches until a transition."},{"name":"Speed","lua_type":"number?","desc":"Set on entry."},{"name":"Random","lua_type":"Random?","desc":"Picks the points. Default `agent.Data.Random`, else a new one."},{"name":"Key","lua_type":"string?","desc":"Default `\\"Search\\"`."},{"name":"Transitions","lua_type":"{ Transition }?","desc":""},{"name":"Enter","lua_type":"((agent: Agent) -> ())?","desc":""},{"name":"Exit","lua_type":"((agent: Agent) -> ())?","desc":""}],"source":{"line":432,"path":"lib/Brain/States.luau"}},{"name":"WanderOptions","desc":"","fields":[{"name":"Home","lua_type":"string | Vector3 | (agent: Agent) -> Vector3?","desc":"The centre to stay around: a key, a position, or a function. Missing means where the agent stood when it first entered the state, kept from then on."},{"name":"Radius","lua_type":"number?","desc":"Studs around home the points are picked in. Default `20`."},{"name":"Pause","lua_type":"number | { number }?","desc":"Seconds to stand at each point. Default `{ 1, 3 }`."},{"name":"Speed","lua_type":"number?","desc":"Set on entry."},{"name":"Random","lua_type":"Random?","desc":"Picks the points and the pauses."},{"name":"Key","lua_type":"string?","desc":"Default `\\"Wander\\"`."},{"name":"Transitions","lua_type":"{ Transition }?","desc":""},{"name":"Enter","lua_type":"((agent: Agent) -> ())?","desc":""},{"name":"Exit","lua_type":"((agent: Agent) -> ())?","desc":""}],"source":{"line":517,"path":"lib/Brain/States.luau"}},{"name":"RoamOptions","desc":"","fields":[{"name":"Interest","lua_type":"Interest","desc":"The map of points to roam. Required."},{"name":"Range","lua_type":"number?","desc":"Studs beyond which a point scores nothing for distance. Default `120`."},{"name":"Tags","lua_type":"{ string }?","desc":"Only points with one of these tags."},{"name":"Linger","lua_type":"number | { number }?","desc":"Seconds to stand at each point before moving on. Default `1`."},{"name":"Duration","lua_type":"number | { number }?","desc":"Seconds to roam before `Then`. Without it, roams until a transition or until no point scores."},{"name":"Then","lua_type":"string?","desc":"The state to enter when time is up or no point is worth a look."},{"name":"Considerations","lua_type":"{ Consideration<InterestPoint> }?","desc":"Extra scoring for [Interest.Best]."},{"name":"Speed","lua_type":"number?","desc":"Set on entry."},{"name":"Random","lua_type":"Random?","desc":"For ranged `Linger` and `Duration`."},{"name":"Key","lua_type":"string?","desc":"Default `\\"Roam\\"`."},{"name":"Transitions","lua_type":"{ Transition }?","desc":""},{"name":"Enter","lua_type":"((agent: Agent) -> ())?","desc":""},{"name":"Exit","lua_type":"((agent: Agent) -> ())?","desc":""}],"source":{"line":607,"path":"lib/Brain/States.luau"}},{"name":"WaitOptions","desc":"","fields":[{"name":"Duration","lua_type":"number | { number }?","desc":"Seconds to stand still before `Then`. Without it the state waits for a transition."},{"name":"Then","lua_type":"string?","desc":"The state to enter when the time is up."},{"name":"Speed","lua_type":"number?","desc":"Set on entry."},{"name":"Random","lua_type":"Random?","desc":"For a ranged `Duration`."},{"name":"Key","lua_type":"string?","desc":"Default `\\"Wait\\"`."},{"name":"Transitions","lua_type":"{ Transition }?","desc":""},{"name":"Enter","lua_type":"((agent: Agent) -> ())?","desc":""},{"name":"Exit","lua_type":"((agent: Agent) -> ())?","desc":""}],"source":{"line":718,"path":"lib/Brain/States.luau"}}],"name":"States","desc":"Factories for the states every enemy ends up writing: [States.Patrol], [States.Investigate],\\n[States.Search], [States.Wander] and [States.Wait]. Exposed as `VluxyAI.States`.\\n\\n```lua\\nlocal States = VluxyAI.States\\nlocal When = VluxyAI.When\\n\\nlocal Brain: VluxyAI.Brain = {\\n\\tInitial = \\"Patrol\\",\\n\\tInterrupts = {\\n\\t\\t{ To = \\"Hunt\\", When = When.Has(\\"SeenTarget\\"), Except = { \\"Hunt\\", \\"Attack\\" } },\\n\\t\\t{ To = \\"Investigate\\", When = When.New(\\"HeardAt\\"), Except = { \\"Hunt\\", \\"Attack\\" } },\\n\\t},\\n\\tStates = {\\n\\t\\tPatrol = States.Patrol({ Points = \\"Nodes\\", Speed = 10 }),\\n\\t\\tInvestigate = States.Investigate({ Target = \\"HeardPosition\\", Speed = 14, Then = \\"Patrol\\" }),\\n\\t\\tHunt = { ... },\\n\\t\\tSearch = States.Search({ Around = \\"SeenPosition\\", Radius = 12, Points = 3, Duration = 14, Then = \\"Patrol\\" }),\\n\\t\\tAttack = VluxyAI.Combat.Attack.State({ ... }),\\n\\t},\\n}\\n```\\n\\n[States.Roam] walks the best point of an [Interest] map, marking each visited, so an enemy\\nthat has lost you checks the places you would plausibly be.\\n\\nEvery factory accepts `Transitions` (checked before the state\'s own logic, like any state),\\n`Enter` and `Exit` hooks run after the built-in ones, `Speed` to set on entry, and `Key`, the\\n`agent.Data` key its scratch lives under (default: the state\'s own name). Positions may be\\ngiven as a blackboard or `Data` key, a `Vector3`, or a function of the agent. A point the\\nnavigator cannot reach is skipped on the next tick, so a search point inside a wall costs\\nnothing but a failed plan.","source":{"line":63,"path":"lib/Brain/States.luau"}}')}}]);